import { expect, expectStatus, test, uniqueName, USERS, type Persona } from "../../fixtures";

const GLOBEX_TENANT = "Globex Procurement";

test.describe("vendor audit trail", () => {
  test("audit trails from another tenant are invisible", { tag: "@AUD-02" }, async ({ apiAs }) => {
    // Arrange: find a seeded persona that belongs to the Globex tenant.
    let globex: Awaited<ReturnType<typeof apiAs>> | undefined;
    for (const persona of Object.keys(USERS) as Persona[]) {
      const candidate = await apiAs(persona);
      const me = await candidate.get("/api/me");
      if (me.ok()) {
        const profile = await expectStatus<{ tenant: { name: string } }>(me, 200);
        if (profile.tenant.name === GLOBEX_TENANT) {
          globex = candidate;
          break;
        }
      }
    }
    expect(globex, `no seeded persona in tenant "${GLOBEX_TENANT}"`).toBeDefined();

    // Arrange: create a vendor inside the Globex tenant.
    const created = await globex!.post("/api/vendors", {
      data: {
        name: uniqueName("AUD-02 Globex Vendor"),
        category: "software",
        contact_email: `aud02-${Date.now()}-${Math.floor(Math.random() * 1e6)}@globex.test`,
      },
    });
    const vendor = await expectStatus<{ id: string }>(created, 201);

    // Arrange: a Northwind member, who must not see Globex data.
    const member = await apiAs("member");

    // Act
    const response = await member.get(`/api/vendors/${vendor.id}/audit`);

    // Assert
    await expectStatus(response, 404);
  });
});
